async function responseJSON(r){const t=await r.text();let d;try{d=JSON.parse(t)}catch{throw Object.assign(Error(r.status===401?'身份验证已过期，请在当前页面重新验证。':'服务返回无效数据（HTTP '+r.status+'）'),{status:r.status})}if(!r.ok)throw Object.assign(Error(d.error?.message|| (typeof d.error==='string'?d.error:JSON.stringify(d.error))||d.message||'服务请求失败（HTTP '+r.status+'）'),{status:r.status});return d;}
