async function load({initial=false,quiet=false}={}){if(!hasConnection()){connected=false;if(initial&&startConnection(true))return;loadError='自动连接未完成，请点击重试连接。';$('#connection').textContent='连接未完成';$('#backend-banner').hidden=false;render();return;}$('#backend-banner').hidden=true;try{if(!quiet)$('#connection').textContent='正在读取资料…';const all=await allBookmarks();records=all.map(item);books=records.filter(b=>!['workspace','conversation'].includes(b.meta.kind));const d=await kara('lists');lists=(d.lists||d||[]).filter(l=>l.type!=='smart');const nextMembers=new Map();for(const list of lists){const rows=await allBookmarks('lists/'+encodeURIComponent(list.id)+'/bookmarks');nextMembers.set(list.id,new Set(rows.map(b=>b.id)))}members=nextMembers;if(workspaceId&&!lists.some(l=>l.id===workspaceId))workspaceId='';connected=true;loadError='';$('#connection').textContent='资料已加载 · '+books.length+' 条';if(!quiet||!$('input:focus,textarea:focus,select:focus'))render();if(!quiet){queueIndexes();schedulePoll();}}catch(e){connected=false;if(initial&&e.status===401&&startConnection(true))return;loadError=e.message;$('#connection').textContent='读取失败 · 重试';if(e.status===401)$('#backend-banner').hidden=false;notice(e.message,true);render();}}
