function filtered(){const q=$('#search').value.trim();let list=scopeBooks().filter(b=>(view!=='inbox'||reading(b)==='unread')&&(!category||b.category===category)&&(!status||reading(b)===status)&&(!typeFilter||resourceType(b)===typeFilter));if(q){const hits=searchChunks(list,q,{limit:300,maxPerDocument:1}),rank=new Map(hits.map((h,i)=>[h.sourceId,i]));list=list.filter(b=>rank.has(b.id)||[b.title,b.reason,b.category,b.userNote].join(' ').toLowerCase().includes(q.toLowerCase())).sort((a,b)=>(rank.get(a.id)??-1)-(rank.get(b.id)??-1));}return list;}
function render(){for(const b of $$('[data-view]'))b.classList.toggle('active',b.dataset.view===view);$('#title').innerHTML=esc(ws()?.name||views[view])+(view==='library'?` <span class="count">${scopeBooks().length}</span>`:'');$('#scope-label').textContent=ws()?'Workspace / '+views[view]:'个人知识库';$('#total-count').textContent=books.length;$('#inbox-count').textContent=books.filter(b=>reading(b)==='unread').length;$('#workspaces').innerHTML=lists.length?lists.map(l=>`<button data-workspace="${esc(l.id)}" class="${l.id===workspaceId?'active':''}"><span>▱</span><span class="workspace-name">${esc(l.name)}</span><b>${books.filter(b=>members.get(l.id)?.has(b.id)).length}</b></button>`).join(''):'<p class="empty-side">按项目建立独立资料空间</p>';$$('[data-workspace]').forEach(b=>b.onclick=()=>selectWorkspace(b.dataset.workspace));$('#category-options').innerHTML=categoryList().map(c=>`<option value="${esc(c)}"></option>`).join('');$('#page-actions').innerHTML=(workspaceId?'<button id="edit-workspace">Workspace 设置</button>':'')+(view!=='graph'?'<button id="index-all" title="更新当前范围内所有来源的全文索引">↻ 更新索引</button>':'');if($('#edit-workspace'))$('#edit-workspace').onclick=()=>openWorkspace(workspaceId);if($('#index-all'))$('#index-all').onclick=()=>task(()=>queueIndexes(true));if(view==='ask')renderAsk();else if(view==='graph')renderGraph();else renderLibrary();bindSources();bindReport();}
