async function saveMeta(id,patch,note,expected){const previous=saveLocks.get(id)||Promise.resolve();const op=previous.catch(()=>{}).then(async()=>{const current=await kara('bookmarks/'+encodeURIComponent(id));if(expected!==undefined&&(current.note||'')!==expected)throw Error('资料已在另一个页面更新，请刷新后再保存。');const old=unpack(current.note||''),merged={...old.meta,...patch,updatedAt:now()},nextNote=pack(note??old.note,merged);if(nextNote.length>2100000)throw Error('本条全文索引超过 2 MB，请拆分文档。原文件仍保留。');const data=await kara('bookmarks/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({note:nextNote})});upsert(data);return data;});saveLocks.set(id,op);try{return await op}finally{if(saveLocks.get(id)===op)saveLocks.delete(id)}}
async function task(fn){try{return await fn()}catch(e){notice(e.message||'操作失败，请重试。',true)}}
async function nativeText(id){let text='',cursor='',version='';for(let i=0;i<35;i++){const d=await kara('bookmarks/'+encodeURIComponent(id)+'/content?format=text&maxChars=50000'+(cursor?'&cursor='+encodeURIComponent(cursor):''));text+=d.content||'';version=d.contentVersion||'';cursor=d.nextCursor;if(!cursor)break;if(i===34)throw Error('正文超过 175 万字符，请拆分文档。')}contentVersions.set(id,version);return text;}
async function pdfPages(data){const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;const doc=await pdfjs.getDocument({data:new Uint8Array(data),isEvalSupported:false,useSystemFonts:true,disableFontFace:true}).promise;try{if(doc.numPages>1000)throw Error('PDF 超过 1000 页，请分卷后建立索引。');let total=0;const pages=[];for(let n=1;n<=doc.numPages;n++){const page=await doc.getPage(n),content=await page.getTextContent();let text='',lastY=null;for(const item of content.items){if(!('str' in item))continue;const y=item.transform?.[5];if(lastY!==null&&Math.abs(y-lastY)>4)text+='\n';text+=item.str+(item.hasEOL?'\n':' ');lastY=y;}text=text.trim();total+=text.length;if(total>1500000)throw Error('PDF 文字超过 150 万字符，请分卷后索引。');pages.push({page:n,text});page.cleanup();}return pages;}finally{await doc.destroy()}}
async function bytesFromAsset(id){const r=await fetch('/karakeep/api/assets/'+encodeURIComponent(id),{signal:AbortSignal.timeout(65000)});if(!r.ok)throw Error('无法读取 PDF 原文件（'+r.status+'）');if(Number(r.headers.get('content-length')||0)>80*1024*1024)throw Error('PDF 超过 80 MiB，请分卷。');return r.arrayBuffer();}
async function getSourcePages(b,{pdfData}={}){if(resourceType(b)==='pdf'||b.content?.assetType==='pdf'){const asset=b.content?.assetId||(b.assets||[]).find(a=>a.assetType==='pdf')?.id;if(!asset&&!pdfData)throw Error('未找到 PDF 原始资产');return {pages:await pdfPages(pdfData||await bytesFromAsset(asset)),parser:'PDF.js 5.6.205'}}if(b.content?.type==='text'){return {pages:[{page:null,text:b.content.text||await nativeText(b.id)}],parser:'native-text'}}let text=await nativeText(b.id);const archive=(b.assets||[]).find(a=>['fullPageArchive','precrawledArchive'].includes(a.assetType));if(archive&&text.length<3000){try{const r=await fetch('/karakeep/api/assets/'+encodeURIComponent(archive.id),{signal:AbortSignal.timeout(45000)});if(r.ok&&Number(r.headers.get('content-length')||0)<12000000){const html=await r.text();if(html.length<12000000){const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('script,style,nav,header,footer,aside,noscript,svg,form').forEach(n=>n.remove());const main=doc.querySelector('article,main,[role=main]')||doc.body;main.querySelectorAll('p,div,li,h1,h2,h3,h4,section,pre,br').forEach(n=>n.append(doc.createTextNode('\n\n')));const archiveText=main.textContent.replace(/[ \t]+/g,' ').replace(/\n\s*\n/g,'\n\n').trim();if(archiveText.length>text.length*1.3&&archiveText.length<1500000)text=archiveText;}}}catch{/* Native readable text remains a valid fallback. */}}if(!text.trim())throw Error('正文尚未抓取，请稍后刷新资料或更新索引。');return {pages:[{page:null,text}],parser:'karakeep-readable-text'}}
async function indexBook(id,options={}){if(indexLocks.has(id))return indexLocks.get(id);const op=(async()=>{let b=books.find(b=>b.id===id);if(!b)return;const {pages,parser}=await getSourcePages(b,options),text=pages.map(p=>p.text).join('\n\n');if(text.length>1500000)throw Error('文字超过 150 万字符，请拆分后索引。');const totalPages=pages.filter(p=>p.page).length,emptyPages=pages.filter(p=>p.page&&!p.text.trim()).map(p=>p.page);const version=await digest(JSON.stringify(pages)),status=!text.trim()?'ocr':emptyPages.length?'partial':'ready';const index={parser:INDEX_VERSION,sourceParser:parser,version,pages,totalPages:totalPages||null,emptyPages,totalCharacters:text.length,crawledAt:b.content?.crawledAt||null,status,indexedAt:now()};await saveMeta(id,{index});texts.set(id,text);contentVersions.set(id,version);return index;})();indexLocks.set(id,op);try{return await op}catch(e){await saveMeta(id,{index:{parser:INDEX_VERSION,status:'error',error:e.message,indexedAt:now()}}).catch(()=>{});throw e}finally{indexLocks.delete(id)}}
async function queueIndexes(force=false){if(indexRunning){if(force)notice('索引任务正在进行中。');return;}indexRunning=true;const candidates=(force?scopeBooks():books).filter(b=>force||['pending','stale'].includes(indexState(b))).filter(b=>b.content?.type==='text'||b.content?.assetType==='pdf'||b.content?.crawlStatus==='success');if(force)notice('正在核对 '+candidates.length+' 条资料的全文版本…');let failed=0;for(const b of candidates){try{await indexBook(b.id)}catch{failed++}}indexRunning=false;if(force)notice('索引更新完成：'+(candidates.length-failed)+' 条成功'+(failed?'，'+failed+' 条需处理（查看资料状态）。':'。'));if(!$('#source-dialog').open&&!$('input:focus,textarea:focus,select:focus'))render();}
async function readText(id,{fresh=false}={}){let b=books.find(b=>b.id===id);if(!b)throw Error('原资料已删除');if(fresh||!['ready','partial','ocr'].includes(indexState(b)))await indexBook(id);b=books.find(b=>b.id===id);const i=b.meta.index;if(i.status==='error')throw Error(i.error);const text=(i.pages||[]).map(p=>p.text).join('\n\n');if(!text.trim())throw Error('此 PDF 没有可提取文字，需要 OCR；原文件仍可打开。');texts.set(id,text);contentVersions.set(id,i.version);return text;}
async function attach(id,listId){if(!listId||members.get(listId)?.has(id))return;await kara('lists/'+encodeURIComponent(listId)+'/bookmarks/'+encodeURIComponent(id),{method:'PUT'});if(!members.has(listId))members.set(listId,new Set());members.get(listId).add(id);}
async function createResource({text='',file=null,title='',workspace='',reason='',category='未分类',type=''}){let request,meta={version:1,reason,category:category||'未分类',reading:'unread',resourceType:type||'note',createdAt:now()};if(file){if(file.size>80*1024*1024)throw Error('文件超过 80 MiB，请分卷。');if(/\.pdf$/i.test(file.name)||file.type==='application/pdf'){meta.resourceType='pdf';const data=await file.arrayBuffer(),hash=await digest(new Uint8Array(data));const duplicate=books.find(b=>b.meta.fileHash===hash);if(duplicate){await attach(duplicate.id,workspace);notice('该 PDF 已存在，已加入所选 Workspace。');return duplicate;}meta.fileHash=hash;$('#add-progress').textContent='正在上传 PDF 原文件…';const form=new FormData();form.append('file',file);const uploaded=await kara('assets',{method:'POST',body:form});request={type:'asset',assetType:'pdf',assetId:uploaded.assetId,fileName:file.name,title:title||file.name.replace(/\.pdf$/i,'')};meta.originalFileName=file.name;}else if(/\.(md|markdown|txt)$/i.test(file.name)){text=await file.text();if(text.length>1500000)throw Error('文字超过 150 万字符，请拆分。');meta.resourceType=type||'document';meta.originalFileName=file.name;request={type:'text',text,title:title||file.name};}else throw Error('支持 PDF、Markdown 和 TXT 文件。');}else if(safeUrl(text)&&!/[\n\r]/.test(text)){const url=canonical(text);const duplicate=books.find(b=>b.url&&canonical(b.url)===url);if(duplicate){await attach(duplicate.id,workspace);notice('该链接已存在，已加入所选 Workspace。');return duplicate;}meta.resourceType=type||'web';request={type:'link',url,...(title?{title}:{})};}else{if(!text.trim())throw Error('请输入链接或笔记内容。');meta.resourceType=type||'note';request={type:'text',text,title:title||text.split('\n')[0].replace(/^#+\s*/,'').slice(0,120)};}const raw=await kara('bookmarks',{method:'POST',body:JSON.stringify({...request,note:pack('',meta)})});const b=upsert(raw);await attach(b.id,workspace);if(request.type!=='link'){try{$('#add-progress').textContent='原文件已保存，正在建立全文索引…';await indexBook(b.id)}catch(e){notice('资料已保存，索引需要处理：'+e.message,true)}}else schedulePoll();return books.find(x=>x.id===b.id)||b;}
function openAdd(type='link'){if(!connected){notice('请先打开资料库。',true);return;}addType=type;$('#add-error').textContent='';$('#add-progress').textContent='';renderAddFields();$('#add-workspace').innerHTML='<option value="">全部资料（暂不加入 Workspace）</option>'+lists.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');$('#add-workspace').value=workspaceId;$('#add-dialog').showModal();}
function renderAddFields(){$$('[data-add-type]').forEach(b=>b.classList.toggle('active',b.dataset.addType===addType));$('#add-fields').innerHTML=addType==='link'?'<label>网页链接<input name="url" type="url" required maxlength="2000" placeholder="https://…" autofocus></label>':addType==='file'?'<label class="drop-zone">选择 PDF、Markdown 或 TXT<input name="file" type="file" accept=".pdf,.md,.markdown,.txt,application/pdf,text/plain,text/markdown" required><p>原文件保存在 VPS 资料库 · PDF 按页建立引用</p></label>':'<label>标题<input name="title" maxlength="200" placeholder="可选"></label><label>笔记内容<textarea name="text" rows="8" required maxlength="1500000" placeholder="写下你的理解，支持 Markdown…"></textarea></label>';}
$('#add-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');button.disabled=true;$('#add-error').textContent='';try{const f=new FormData(form),file=addType==='file'?f.get('file'):null;await createResource({text:String(f.get(addType==='link'?'url':'text')||''),title:String(f.get('title')||''),file,workspace:String(f.get('workspaceId')||''),reason:String(f.get('reason')||''),category:String(f.get('category')||'未分类'),type:String(f.get('resourceType')||'')});form.reset();$('#add-dialog').close();await load({quiet:true});render();notice('已保存到资料库。')}catch(e){$('#add-error').textContent=e.message}finally{button.disabled=false}};
